/* Container: centred column with side padding. */
.container { width: 100%; margin-inline: auto; padding-inline: var(--s5); }
.container-text { max-width: calc(var(--measure) + 2 * var(--s5)); }
.container-page { max-width: calc(var(--content) + 2 * var(--s5)); }
.container-full { max-width: none; }

.heading { font-weight: 500; line-height: 1.15; text-wrap: balance; }
.heading-display { font-family: var(--font-display); font-weight: 700; font-size: var(--display-md); letter-spacing: -0.035em; line-height: 0.95; }
.heading-xl { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.heading-lg { font-size: calc(var(--text-lg) * 1.35); }
.heading-md { font-size: var(--text-lg); }
.heading-sm { font-size: var(--text-base); }

.text { max-width: var(--measure); }
.text-xs { font-size: var(--text-xs); } .text-sm { font-size: var(--text-sm); } .text-md { font-size: var(--text-base); } .text-lg { font-size: var(--text-lg); }
.text-muted { color: var(--muted); } .text-danger { color: var(--danger); } .text-ok { color: var(--ok); } .text-accent { color: var(--accent-text); }
.text-truncate { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }

/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 14px 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { padding: 6px 12px; font-size: var(--text-xs); }
.btn-block { width: 100%; }

/* ─── Marks ─── */
.swatch { width: 14px; height: 14px; flex: none; margin-top: 4px; display: inline-block; }
.check { width: 20px; height: 20px; flex: none; display: grid; place-items: center; font-size: var(--text-xs); font-weight: 500; margin-top: 2px; }
.check-pass { border: 1px solid var(--foreground); }
.check-fail { background: var(--accent); color: var(--on-accent); }
.badge { display: inline-flex; align-items: center; gap: var(--s1); padding: 2px 8px; font-size: var(--text-xs); font-weight: 500; border: 1px solid var(--rule); white-space: nowrap; }
.badge-solid { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.badge-accent { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.kbd { display: inline-block; padding: 0 6px; font-size: var(--text-xs); border: 1px solid var(--rule); border-bottom-width: 2px; line-height: 18px; }
/* A line of keyboard hints under a field: each key with its word, groups --s3 apart. */
.key-hints { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s1) var(--s3); font-size: var(--text-xs); color: var(--muted); }
.key-hints > span { display: inline-flex; align-items: center; gap: var(--s1); }
.dot { width: 8px; height: 8px; border-radius: var(--round); background: var(--accent); display: inline-block; flex: none; }

/* Heat: five steps of the app's accent, for counts over time. */
.heat-0 { background: var(--wash-2); }
.heat-1 { background: color-mix(in srgb, var(--accent) 25%, var(--background)); }
.heat-2 { background: color-mix(in srgb, var(--accent) 50%, var(--background)); }
.heat-3 { background: color-mix(in srgb, var(--accent) 75%, var(--background)); }
.heat-4 { background: var(--accent); }

/* Segmented control: joined toggles, one always on. */
.segmented { display: inline-flex; border: 1px solid var(--foreground); }
.segment { padding: var(--s2) var(--s4); font-size: var(--text-sm); color: var(--muted); background: transparent; }
.segment + .segment { border-inline-start: 1px solid var(--rule); }
.segment:hover:not(:disabled) { color: var(--foreground); }
.segment[data-state="on"] { background: var(--foreground); color: var(--background); }
.segment:disabled { opacity: 0.5; cursor: not-allowed; }
.segment:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

/* Block: pricing. */
.block-pricing { padding-block: var(--s8); }
.block-pricing-head { display: flex; flex-direction: column; align-items: flex-start; gap: var(--s3); max-width: var(--measure); margin-bottom: var(--s7); }
.block-pricing-head .segmented { margin-top: var(--s3); }
.block-pricing-tiers { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--s5); grid-template-columns: 1fr; }
.block-tier { display: flex; flex-direction: column; gap: var(--s4); padding: var(--s5); border: 1px solid var(--rule); min-width: 0; }
.block-tier[data-highlighted] { border-color: var(--foreground); }
.block-tier-head { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); }
.block-tier-price { display: flex; align-items: baseline; gap: var(--s2); }
.block-tier-amount { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.block-tier-period { font-size: var(--text-sm); color: var(--muted); }
.block-tier-features { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--s2); flex: 1; font-size: var(--text-sm); }
.block-tier-features li { padding-top: var(--s2); border-top: 1px solid var(--rule); }
@media (min-width: 760px) { .block-pricing-tiers { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); } }

